```
// 1. Setup: Create replica with COMMITTED instances
replica := newReplica(id, n)
instances := createCommittedInstances(replica, commands)

// 2. Execute commands and verify EXECUTED status in memory
for _, inst := range instances {
    replica.exec.executeCommand(inst.replica, inst.instance)
    assert(inst.Status == EXECUTED)
}
verifyStateMachineUpdated(replica, expectedState)

// 3. Simulate crash: create new replica with COMMITTED instances
replicaPrime := newReplica(id, n)
for _, inst := range instances {
    replicaPrime.createInstance(inst.replica, inst.instance, inst.cmds, COMMITTED, inst.seq, inst.deps)
}
// ExecedUpTo is reset to initial value (-1 or 0)
// State machine is empty

// 4. Attempt re-execution
for _, inst := range instances {
    replicaPrime.exec.executeCommand(inst.replica, inst.instance)
}

// 5. Check for duplicate execution
if instancesAreExecutedAgain(replicaPrime) {
    // BUG: Duplicate execution occurred
    reportBug("Execution status not persisted, causing duplicate execution")
} else {
    // CORRECT: Re-execution was prevented
}
```

Key assertions:
- Verify instances transition from COMMITTED to EXECUTED twice
- Verify state machine is updated twice (or would be for non-idempotent ops)
- Check if execution status is persisted after execution
- Check if ExecedUpTo is persisted and used to prevent re-execution
